const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const mobileScreen=$('#mobile-screen');
const portalScreen=$('#portal-screen');
const dialog=$('#prototype-dialog');
let toastTimer;

function showToast(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)}
function pill(label,type='neutral'){return `<span class="pill ${type}">${label}</span>`}
function icon(name){const paths={bell:'<path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 8h18c0-1-3-1-3-8Z"/><path d="M10 21h4"/>',arrow:'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16.5 16.5 4 4"/>',settings:'<path d="M4 6h10M18 6h2M4 12h3M11 12h9M4 18h8M16 18h4"/><circle cx="16" cy="6" r="2"/><circle cx="9" cy="12" r="2"/><circle cx="14" cy="18" r="2"/>',card:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h4"/>',heart:'<path d="M20.8 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.5a5.5 5.5 0 0 0 0-7.8Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.4 2.4 0 1 1 3.5 2.1c-1 .5-1.3 1-1.3 2M12 17h.01"/>'};return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.heart}</svg>`}
function mobileHeader(title,back='home',action=''){return `<header class="mobile-page-header"><button class="back-button" data-mobile-screen="${back}" aria-label="Nazad">${icon('arrow')}</button><h2>${title}</h2>${action||'<span style="width:40px"></span>'}</header>`}
function eventCard(name,city,date='12',day='SUB',time='10:00-14:00',screen='action-detail'){return `<button class="event-card" data-mobile-screen="${screen}"><span class="date-tile"><span>${day}</span><strong>${date}</strong><span>OKT</span></span><span class="event-info"><strong>${name}</strong><span>${city}</span><span>${time}</span></span><span class="chevron">›</span></button>`}

function renderMobileList(){
  $('#mobile-screen-list').innerHTML=mobileCatalog.map(group=>`<section class="screen-group"><h3>${group.title}</h3>${group.items.map(([id,label])=>`<button data-mobile-screen="${id}">${label}</button>`).join('')}</section>`).join('');
}

function renderChecklist(){
  const items=screenDecisions[state.mobileScreen]||screenDecisions.home;
  $('#decision-checklist').innerHTML=items.map((item,index)=>`<div class="check-item"><span>${index+1}</span><div><strong>${item[0]}</strong><small>${item[1]}</small></div></div>`).join('');
}

function renderMobile(screen=state.mobileScreen){
  state.mobileScreen=screen;
  const labels=Object.fromEntries(mobileCatalog.flatMap(group=>group.items));
  $('#mobile-flow-label').textContent=labels[screen]||screen;
  $$('#mobile-screen-list [data-mobile-screen]').forEach(button=>button.classList.toggle('active',button.dataset.mobileScreen===screen));
  const root={actions:'actions','action-detail':'actions',booking:'actions','booking-success':'actions',appointments:'actions',notifications:'notifications',profile:'profile',card:'profile',history:'profile','donation-detail':'profile',corrections:'profile',achievements:'profile',privacy:'profile',pause:'profile',questionnaire:'profile'}[screen]||'home';
  const onboarding=['welcome','registration','verification','link-record'].includes(screen);
  $('#mobile-nav').classList.toggle('hidden',onboarding);
  $$('#mobile-nav [data-mobile-screen]').forEach(button=>button.classList.toggle('active',button.dataset.mobileScreen===root));
  mobileScreen.innerHTML=mobileTemplates[screen]?.()||mobileTemplates.home();
  mobileScreen.scrollTop=0;
  renderChecklist();
  history.replaceState(null,'',`#mobile/${screen}`);
}

